def read_large_file(path):
    with open(path) as f:
        for line in f:
            yield line.rstrip("\n")

for line in read_large_file("events.log"):
    process(line)

def parse(lines):
    for line in lines:
        yield json.loads(line)

def only_errors(records):
    for r in records:
        if r["level"] == "ERROR":
            yield r

raw = read_large_file("events.log")
for err in only_errors(parse(raw)):
    alert(err)
